import type { Deployment, DeploymentCreate, DeploymentUpdate } from './model';
import { DeploymentRepository, DeploymentNotFoundError } from './repository';
import { validateDeploymentCreate, validateDeploymentUpdate } from './validator';

export interface DeploymentServiceDeps {
  repository: DeploymentRepository;
  clock?: () => Date;
  logger?: (msg: string, meta?: Record<string, unknown>) => void;
}

export interface ListDeploymentOptions {
  offset?: number;
  limit?: number;
  sortBy?: keyof Deployment;
  order?: 'asc' | 'desc';
}

/**
 * Business-logic layer above DeploymentRepository.
 */
export class DeploymentService {
  private readonly repo: DeploymentRepository;
  private readonly clock: () => Date;
  private readonly logger: (msg: string, meta?: Record<string, unknown>) => void;

  constructor(deps: DeploymentServiceDeps) {
    this.repo = deps.repository;
    this.clock = deps.clock ?? (() => new Date());
    this.logger = deps.logger ?? (() => { /* noop */ });
  }

  create(input: DeploymentCreate): Deployment {
    const errors = validateDeploymentCreate(input);
    if (errors.length > 0) throw new DeploymentValidationError(errors);
    const created = this.repo.insert(input);
    this.logger('DeploymentService.create', { id: created.id });
    return created;
  }

  get(id: string): Deployment {
    return this.repo.requireById(id);
  }

  tryGet(id: string): Deployment | undefined {
    return this.repo.findById(id);
  }

  update(id: string, patch: DeploymentUpdate): Deployment {
    const errors = validateDeploymentUpdate(patch);
    if (errors.length > 0) throw new DeploymentValidationError(errors);
    const updated = this.repo.update(id, patch);
    this.logger('DeploymentService.update', { id });
    return updated;
  }

  delete(id: string): void {
    const existed = this.repo.delete(id);
    if (!existed) throw new DeploymentNotFoundError(id);
    this.logger('DeploymentService.delete', { id });
  }

  list(options: ListDeploymentOptions = {}): Deployment[] {
    const offset = options.offset ?? 0;
    const limit = options.limit ?? 50;
    if (options.sortBy) {
      const sorted = this.repo.sortedBy(options.sortBy, options.order);
      return sorted.slice(offset, offset + limit);
    }
    return this.repo.paginate(offset, limit);
  }

  countAll(): number {
    return this.repo.count();
  }

  batchCreate(inputs: DeploymentCreate[]): Deployment[] {
    for (const input of inputs) {
      const errors = validateDeploymentCreate(input);
      if (errors.length > 0) throw new DeploymentValidationError(errors);
    }
    return this.repo.batchInsert(inputs);
  }

  exists(id: string): boolean {
    return this.repo.findById(id) !== undefined;
  }

  bulkDelete(ids: string[]): number {
    let deleted = 0;
    for (const id of ids) if (this.repo.delete(id)) deleted++;
    return deleted;
  }

  searchByField<K extends keyof Deployment>(field: K, value: Deployment[K]): Deployment[] {
    return this.repo.filter((entity) => entity[field] === value);
  }
}

export class DeploymentServiceError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'DeploymentServiceError';
  }
}

export class DeploymentValidationError extends Error {
  constructor(public readonly errors: string[]) {
    super(`Deployment validation failed: ${errors.join('; ')}`);
    this.name = 'DeploymentValidationError';
  }
}
